/**
 * Identifiers.
 *
 * Every document in this system carries a UUIDv7 generated by the CLIENT, not
 * the server. That is what makes offline sync idempotent: a device creates an
 * invoice with no network, retries the upload three times over a flaky
 * connection, and the server stores exactly one row because the primary key
 * came with the request.
 *
 * v7 over v4 because v7 is time-ordered. Random v4 keys scatter inserts across
 * a B-tree and fragment it; v7 keys append, which keeps index writes local and
 * makes `ORDER BY id` a usable proxy for creation order.
 */
import { v7 as uuidv7, validate as uuidValidate, version as uuidVersion } from 'uuid';

export type Uuid = string;

/** Server-side generation, for rows the client never creates (audit entries). */
export function newId(): Uuid {
  return uuidv7();
}

/** Any valid UUID, of any version. */
export function isUuid(value: unknown): value is Uuid {
  return typeof value === 'string' && uuidValidate(value);
}

/**
 * Accepts v4 as well as v7. Clients on older builds still send v4, and
 * rejecting those would break their sync — the ordering benefit is an
 * optimisation, not a correctness requirement.
 */
export function isClientDocumentId(value: unknown): value is Uuid {
  if (!isUuid(value)) return false;
  const version = uuidVersion(value);
  return version === 7 || version === 4;
}

/**
 * The timestamp embedded in a v7 id. Useful for diagnosing sync ordering
 * without a round-trip to the database. Returns undefined for other versions.
 */
export function timestampFromUuidV7(id: Uuid): Date | undefined {
  if (!isUuid(id) || uuidVersion(id) !== 7) return undefined;
  // The first 48 bits are a big-endian Unix millisecond timestamp.
  const hex = id.replace(/-/g, '').slice(0, 12);
  return new Date(Number.parseInt(hex, 16));
}

/**
 * A short, unambiguous, human-quotable code — used for support references and
 * idempotency fallbacks.
 *
 * Crockford's alphabet without I, L, O and U: removes the 1/I/L and 0/O
 * confusions when a shopkeeper reads a code down the phone, and drops U so the
 * generator cannot produce an offensive word by chance.
 */
const SHORT_CODE_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

export function shortCode(length = 8): string {
  const bytes = crypto.getRandomValues(new Uint8Array(length));
  let output = '';
  for (const byte of bytes) {
    output += SHORT_CODE_ALPHABET[byte % SHORT_CODE_ALPHABET.length];
  }
  return output;
}
